import math
def ai_release_reasons(required,results,tokens,latency,max_tokens,max_latency):
    if any(not isinstance(x,(int,float)) or not math.isfinite(x) or x<0 for x in [tokens,latency]):return ['invalid usage']
    reasons=[f'case:{key}' for key in sorted(set(required)) if results.get(key) is not True]
    if tokens>max_tokens:reasons.append('tokens')
    if latency>max_latency:reasons.append('latency')
    return reasons

